$(document).ready(function(){$("#legal_imprint").change(function(){OC.msg.startSaving("#legal_imprint");var i={imprintUrl:$("#legal_imprint").val()};$.post(OC.generateUrl("/settings/admin/legal/imprint"),i,function(i){OC.msg.finishedSaving("#legal_imprint_msg",i)})}),$("#legal_privacy_policy").change(function(){OC.msg.startSaving("#legal_privacy_policy");var i={privacyPolicy:$("#legal_privacy_policy").val()};$.post(OC.generateUrl("/settings/admin/legal/privacypolicy"),i,function(i){OC.msg.finishedSaving("#legal_privacy_policy_msg",i)})})});